/* ТИПОГРАФ. Приводит текст к правилам русского набора: кавычки ёлочками, тире
   вместо дефиса, неразрывные пробелы там, где перенос строки разорвал бы смысл,
   знаки © ® ™ × и многоточие.

   Всё считается здесь, без сервиса: правила короткие, а отправлять содержимое
   книги на чужой сервер ради кавычек — плохая мена.

   ОДИН ПЛАГИН НА ДВА ПРИЛОЖЕНИЯ. Правила — общие; разное только «откуда взять
   текст и куда положить». Где есть `лист` — работаем по клеткам, где есть
   `документ` — по абзацам. В документе правила применяются к тексту МЕЖДУ
   тегами, поэтому оформление внутри абзаца остаётся на месте; кавычка,
   открытая до курсива и закрытая после, при этом парой не считается. */
const вДокументе = typeof документ !== 'undefined';

const НЕРАЗРЫВ = ' ', ТИРЕ = '—', СРЕДНЕЕ = '–';
const ЁЛКА1 = '«', ЁЛКА2 = '»', ЛАПКА1 = '„', ЛАПКА2 = '“';
const ПРЕДЛОГИ = 'а|в|во|да|до|же|за|и|из|к|ко|ли|на|над|не|ни|но|о|об|от|по|под|при|с|со|та|то|у|уж|что|бы|ль';

const ПРАВИЛА = [
  {ключ: 'кавычки', делать: т => {
    let из = т.replace(/\"([^\"]*)\"/g, (в, с) => ЁЛКА1 + с + ЁЛКА2);
    /* вложенные кавычки — лапками, как принято в русском наборе */
    const внутри = new RegExp(ЁЛКА1 + '([^' + ЁЛКА1 + ЁЛКА2 + ']*)' + ЁЛКА1 + '([^' + ЁЛКА1 + ЁЛКА2 + ']*)' + ЁЛКА2 + '([^' + ЁЛКА1 + ЁЛКА2 + ']*)' + ЁЛКА2, 'g');
    return из.replace(внутри, (в, a, b, c) => ЁЛКА1 + a + ЛАПКА1 + b + ЛАПКА2 + c + ЁЛКА2);
  }},
  {ключ: 'тире', делать: т => т
    .replace(/(^|[\s (])-([\s ])/g, (в, п, х) => п + ТИРЕ + х)
    .replace(/(\d)\s*-\s*(\d)/g, (в, a, b) => a + СРЕДНЕЕ + b)},
  {ключ: 'многоточие', делать: т => т.replace(/\.{3,}/g, '…')},
  {ключ: 'знаки', делать: т => т
    .replace(/\((?:c|с)\)/gi, '©').replace(/\(r\)/gi, '®').replace(/\(tm\)/gi, '™')
    .replace(/(\d)\s*[xх]\s*(\d)/g, (в, a, b) => a + '×' + b)},
  {ключ: 'пробелы', делать: т => т
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/[ \t]+([,.;:!?…])/g, (в, з) => з)
    .replace(/([,;:!?])(?=[A-Za-zА-яЁё])/g, (в, з) => з + ' ')
    .replace(/\(\s+/g, '(').replace(/\s+\)/g, ')')},
  {ключ: 'предлоги', делать: т =>
    т.replace(new RegExp('(^|[\\s\\u00A0(' + ЁЛКА1 + '])(' + ПРЕДЛОГИ + ')[ \\t]', 'gi'), (в, п, с) => п + с + НЕРАЗРЫВ)},
  {ключ: 'единицы', делать: т => т
    .replace(/(\d)[ \t]+(%|№|руб\.|коп\.|тыс\.|млн|млрд|кг|км|см|мм|мл|шт\.|мин|ч|г|т|м|л|с)(?![\wа-яё])/gi, (в, ч, е) => ч + НЕРАЗРЫВ + е)
    .replace(/(№|\$|₽)[ \t]+(\d)/g, (в, з, ч) => з + НЕРАЗРЫВ + ч)
    .replace(/(^|[\s (])(гг|вв|стр|рис|табл|им|ул|кв|г|в)\.[ \t]+/gi, (в, п, с) => п + с + '.' + НЕРАЗРЫВ)},
  {ключ: 'тиреНеразрыв', делать: т => т.replace(new RegExp('[ \\t]+' + ТИРЕ, 'g'), НЕРАЗРЫВ + ТИРЕ)},
];

function обработать(текст, п){
  let из = String(текст);
  for(const пр of ПРАВИЛА) if(п[пр.ключ] !== false) из = пр.делать(из);
  return из;
}

/* Неразрывный пробел в предпросмотре виден как ␣ — иначе не отличить от обычного */
const видно = т => т.replace(/ /g, '␣');

async function Предпросмотр(){
  if(вДокументе) return ПредпросмотрДок();
  const п = параметры({}), в = книга.выделение;
  if(!в){ панель.список('образец', [['', 'выделите клетки']]); return; }
  const строки = await лист(в.лист).прочитать(в.область);
  const ряды = [];
  for(const р of строки){
    for(const з of р){
      if(ряды.length >= 8) break;
      if(typeof з !== 'string' || !з.trim()) continue;
      const стало = обработать(з, п);
      if(стало !== з) ряды.push([видно(з).slice(0, 44), видно(стало).slice(0, 44)]);
    }
    if(ряды.length >= 8) break;
  }
  панель.список('образец', ряды.length ? ряды : [['', 'править нечего']]);
}

async function Применить(){
  if(вДокументе) return ПрименитьДок();
  const п = параметры({}), в = книга.выделение;
  if(!в){ панель.сообщение('Сначала выделите клетки'); return; }
  const строки = await лист(в.лист).прочитать(в.область);
  let тронуто = 0;
  const новые = строки.map(р => р.map(з => {
    if(typeof з !== 'string') return з;
    const стало = обработать(з, п);
    if(стало !== з) тронуто++;
    return стало;
  }));
  if(!тронуто){ панель.сообщение('Всё уже по правилам: ' + в.область); return; }
  лист(в.лист).диапазон(в.область).записать(новые);
  панель.сообщение('Поправлено клеток: ' + тронуто + ' в ' + в.область);
  Предпросмотр();
}

/* --- документ -------------------------------------------------------------- */
/* --- документ -------------------------------------------------------------
   Правила — к тексту МЕЖДУ тегами: при разбивке по тегам текст это чётные
   куски. Так оформление внутри абзаца (курсив, ссылка, поле) остаётся на
   месте, а кавычка, открытая до курсива и закрытая после, парой не считается.
*/
const поТексту = (html, f) => String(html).split(/(<[^>]*>)/).map((ч, i) => i % 2 ? ч : f(ч)).join('');

/* Какие абзацы берём: тот, где стоит курсор или что-то выделено, а без
   выделения — все. */
function абзацыДок(){
  const в = документ.выделение || {};
  if(в.блок >= 0 && (в.есть || в.текст)) return [в.блок];
  return документ.блоки.map((б, i) => i);
}

function ПредпросмотрДок(){
  const п = параметры({});
  const блоки = документ.блоки, где = абзацыДок();
  const ряды = [];
  for(const и of где){
    const б = блоки[и]; if(!б || !б.текст.trim()) continue;
    const стало = обработать(б.текст, п);
    if(стало === б.текст) continue;
    ряды.push([видно(б.текст).slice(0, 44), видно(стало).slice(0, 44)]);
    if(ряды.length >= 8) break;
  }
  панель.список('образец', ряды.length ? ряды : [['', 'править нечего']]);
}

function ПрименитьДок(){
  const п = параметры({});
  const блоки = документ.блоки, где = абзацыДок();
  let тронуто = 0;
  for(const и of где){
    const б = блоки[и]; if(!б || !б.текст.trim()) continue;
    const html = поТексту(б.html, т => обработать(т, п));
    if(html === б.html) continue;
    документ.правитьБлок(и, {html: html});
    тронуто++;
  }
  панель.сообщение(тронуто
    ? 'Поправлено абзацев: ' + тронуто + (где.length === блоки.length ? ' (весь документ)' : '')
    : 'Всё уже по правилам');
  ПредпросмотрДок();
}

function Старт(){ Предпросмотр(); }
